/// </summary>
/// <param name="_salesTable">The source SalesTable record.</param>
/// <returns>A new populated instance of <c>AAXSalesReturnOrderCreatedBusinessEventContract</c>.</returns>
public static AAXSalesReturnOrderCreatedBusinessEventContract newFromSalesTable(SalesTable _salesTable)
{
    var contract = new AAXSalesReturnOrderCreatedBusinessEventContract();
    contract.initialize(_salesTable);

    return contract;
}

/// <summary>
/// Initializes the contract fields from the source record.
/// </summary>
/// <param name="_salesTable">The source SalesTable record.</param>
private void initialize(SalesTable _salesTable)
{
    legalEntity = _salesTable.DataAreaId;
    returnOrderId = _salesTable.SalesId;
    customerAccount = _salesTable.CustAccount;
    returnReasonCodeId = _salesTable.ReturnReasonCodeId;
}

